referenceSolutions.javascript:
function facingCardsFirstQualifyingSlip(readings, k) {
  const a=readings; let out=[];
  for(let l=0,r=a.length-1;l<=r;l++,r--)out.push(l===r?a[l]:a[l]+a[r]);
  return out.find(x=>x>=k)??-1;
}

