referenceSolutions.python:
def facingCardsFirstQualifyingSlip(readings, k):
    a=readings
    out=[]
    l,r=0,len(a)-1
    while l<=r:
        out.append(a[l] if l==r else a[l]+a[r])
        l+=1
        r-=1
    return next((x for x in out if x>=k),-1)

